const ref=new URL(url).hostname.split(".")[0];
const name=`sb-${ref}-auth-token`;
const val="base64-"+Buffer.from(JSON.stringify(data.session)).toString("base64url");
const CH=3180; const parts=[];
for(let i=0;i<val.length;i+=CH) parts.push(val.slice(i,i+CH));
const cookie = parts.length===1 ? `${name}=${val}` : parts.map((p,i)=>`${name}.${i}=${p}`).join("; ");
require("fs").writeFileSync("/tmp/cookie.txt", cookie);
console.log("세션 쿠키 생성 · 조각", parts.length+"개");
})'

