const u=get("PUBLIC_SUPABASE_URL"); const sk=get("SUPABASE_SERVICE_ROLE_KEY");
const isLocal=/127\.0\.0\.1|localhost/.test(u);
console.log("PUBLIC_SUPABASE_URL:", u || "(빈 값)");
