import { describe, expect, it } from "vitest";
import { configureDb } from "../packages/db/src/server/config.server";
import {
  countPendingChannels, getSeller, listPendingChannels, listSellers,
  setChannelVerified, setSellerActive, setSellerHidden,
} from "../packages/db/src/server/admin/sellers.server";

configureDb({ url: process.env.PUBLIC_SUPABASE_URL, serviceKey: process.env.SUPABASE_SERVICE_ROLE_KEY });

describe("sellers.server (로컬 Supabase)", () => {
  it("listSellers — 전체 + 카운트", async () => {
    const r = await listSellers();
    console.log("  rows:", r.rows.length, "counts:", JSON.stringify(r.counts));
    expect(r.rows.length).toBeGreaterThan(0);
  });
  it("listSellers — 필터", async () => {
    for (const f of ["active", "suspended", "hidden", "pending_channel"] as const) {
      const r = await listSellers({ filter: f });
      console.log(`  ${f}: ${r.rows.length}건`);
    }
  });
  it("listSellers — 검색", async () => {
    const r = await listSellers({ q: "jiyu" });
    console.log("  q=jiyu:", r.rows.map((x) => `${x.code} ${x.name}`).join(", "));
    expect(r.rows.length).toBeGreaterThan(0);
  });
  it("getSeller — code / uuid / 없는 값", async () => {
    const byCode = await getSeller("s1");
    console.log("  s1:", byCode?.seller.name, "채널", byCode?.channels.length);
    expect(byCode).not.toBeNull();
    const byId = await getSeller(byCode!.seller.id);
    expect(byId?.seller.code).toBe("s1");
    expect(await getSeller("nope")).toBeNull();
  });
  it("listPendingChannels + countPendingChannels", async () => {
    const q = await listPendingChannels();
    console.log("  대기:", q.map((c) => `${c.platform} ${c.handle} (${c.seller?.name}) vcode=${c.vcode}`).join(" | "));
    expect(await countPendingChannels()).toBe(q.length);
  });
  it("setSellerHidden — 토글 후 원복 (신규 쓰기 경로)", async () => {
    const before = (await getSeller("s1"))!.seller.hidden;
    expect((await setSellerHidden("s1", !before)).ok).toBe(true);
    expect((await getSeller("s1"))!.seller.hidden).toBe(!before);
    expect((await setSellerHidden("s1", before)).ok).toBe(true);
    expect((await getSeller("s1"))!.seller.hidden).toBe(before);
  });
  it("setSellerActive — 정지 후 복귀", async () => {
    expect((await setSellerActive("s3", false, "테스트")).code).toBe("suspended");
    expect((await getSeller("s3"))!.seller.active).toBe(false);
    expect((await setSellerActive("s3", false)).ok).toBe(true); // 멱등
    expect((await setSellerActive("s3", true)).code).toBe("reactivated");
    expect((await getSeller("s3"))!.seller.active).toBe(true);
  });
  it("setChannelVerified — 승인 후 원복", async () => {
    const q = await listPendingChannels();
    if (q.length === 0) return console.log("  대기 건 없음 — 건너뜀");
    const ch = q[0];
    expect((await setChannelVerified(ch.id, true)).code).toBe("channel_verified");
    const after = (await getSeller(ch.seller_id))!.channels.find((c) => c.id === ch.id)!;
    expect(after.verified).toBe(true);
    expect(after.vcode).toBeNull();
    expect((await setChannelVerified(ch.id, false)).code).toBe("channel_unverified");
  });
  it("없는 대상은 err_not_found", async () => {
    expect((await setSellerActive("nope", false)).code).toBe("err_not_found");
    expect((await setChannelVerified("nope", true)).code).toBe("err_not_found");
  });
});
EOF
