import { redirect } from '@sveltejs/kit';
import type { PageServerLoad } from './$types';
import { SELLER_ACTION_MESSAGES, SELLER_FILTER_LABELS, SELLER_FILTERS, parseSellerFilter } from '@sellery/db/admin/seller-rules';
import { adminPath, requireAdmin } from '$lib/server/admin';
import { listSellers } from '$lib/server/partners';

/**
 * `/sellers` — 인플루언서 목록 (docs/admin-console-plan.md "파트너 관리" · `partner-admin.mjs list` 의 화면 판).
 * load: `requireAdmin` → `listSellers({ filter, q })`. 상단 띠(전체 · 정지 · 비공개 · 채널 인증 대기) · 필터 칩 · 검색 · 표.
 * 쓰기(정지 · 비공개 · 채널 승인)는 전부 상세(`/sellers/[code]`)에서 — 목록에서 실수로 누르는 것을 막는다.
 * `?msg=` 는 상세 액션이 목록으로 돌아올 때의 결과 문구(`SELLER_ACTION_MESSAGES`).
 */
export const load: PageServerLoad = async (event) => {
	const gate = await requireAdmin(event);
	if (!gate.ok) redirect(303, gate.location);

	const filter = parseSellerFilter(event.url.searchParams.get('filter'));
	const q = (event.url.searchParams.get('q') ?? '').trim();
	const { rows, counts } = await listSellers({ filter, q: q || null });

	const self = adminPath('/sellers');
	const key = event.url.searchParams.get('msg') ?? '';
	const msg = key ? (SELLER_ACTION_MESSAGES[key] ?? null) : null;

	return {
		rows,
		counts,
		filter,
		q,
		msg,
		msgTone: key.startsWith('err') ? ('danger' as const) : ('ok' as const),
		self,
		chips: SELLER_FILTERS.map((f) => ({
			key: f,
			label: SELLER_FILTER_LABELS[f],
			href: f === 'all' ? self : `${self}?filter=${f}`
		}))
	};
};

